1	import { randomUUID } from "node:crypto";
2	
3	import { trace } from "neatlogs";
4	
5	import { clearSmokeGraphThread } from "@/lib/agent/smoke-checkpointer";
6	import { smokeGraph, smokeGraphInput } from "@/lib/agent/smoke-graph";
7	import { isSmokeEndpointEnabled } from "@/lib/agent/smoke-access";
8	import { createNeatlogsHandler, flushNeatlogs } from "@/lib/neatlogs";
9	
10	export const runtime = "nodejs";
11	
12	const encoder = new TextEncoder();
13	
14	function sse(event: string, data: unknown) {
15	  return encoder.encode(`event: ${event}\ndata: ${JSON.stringify(data)}\n\n`);
16	}
17	
18	export async function POST(request: Request) {
19	  if (!isSmokeEndpointEnabled(process.env)) {
20	    return new Response("Not found", { status: 404 });
21	  }
22	
23	  const runId = randomUUID();
24	  const graphAbort = new AbortController();
25	  let cancelled = false;
26	  const abortGraph = () => graphAbort.abort(request.signal.reason);
27	  request.signal.addEventListener("abort", abortGraph, { once: true });
28	
29	  const body = await request.json().catch(() => ({}));
30	  const domain =
31	    typeof body === "object" &&
32	    body !== null &&
33	    "domain" in body &&
34	    typeof body.domain === "string"
35	      ? body.domain
36	      : "example.com";
37	
38	  const stream = new ReadableStream<Uint8Array>({
39	    async start(controller) {
40	      try {
41	        await trace({ name: "POST", kind: "WORKFLOW" }, async () => {
42	          const handler = await createNeatlogsHandler();
43	          controller.enqueue(sse("run", { runId }));
44	
45	          const events = await smokeGraph.stream(smokeGraphInput(domain), {
46	            configurable: { thread_id: runId },
47	            streamMode: ["updates", "messages"],
48	            callbacks: [handler],
49	            tags: ["variant:smoke"],
50	            runId,
51	            signal: graphAbort.signal,
52	          });
53	
54	          for await (const event of events) {
55	            controller.enqueue(sse("graph", event));
56	          }
57	
58	          controller.enqueue(sse("done", { runId }));
59	        });
60	      } catch (error) {
61	        if (!graphAbort.signal.aborted) {
62	          controller.enqueue(
63	            sse("error", {
64	              runId,
65	              message: error instanceof Error ? error.message : "Unknown error",
66	            }),
67	          );
68	        }
69	      } finally {
70	        request.signal.removeEventListener("abort", abortGraph);
71	        await Promise.all([
72	          clearSmokeGraphThread(runId),
73	          flushNeatlogs().catch(() => false),
74	        ]);
75	        if (!cancelled) {
76	          controller.close();
77	        }
78	      }
79	    },
80	    cancel(reason) {
81	      cancelled = true;
82	      graphAbort.abort(reason);
83	    },
84	  });
85	
86	  return new Response(stream, {
87	    headers: {
88	      "Cache-Control": "no-cache, no-transform",
89	      Connection: "keep-alive",
90	      "Content-Type": "text/event-stream; charset=utf-8",
91	    },
92	  });
93	}
