1	import { HumanMessage } from "@langchain/core/messages";
2	import { tool } from "@langchain/core/tools";
3	import {
4	  END,
5	  MessagesAnnotation,
6	  START,
7	  StateGraph,
8	} from "@langchain/langgraph";
9	import { ToolNode } from "@langchain/langgraph/prebuilt";
10	import { span } from "neatlogs";
11	import { z } from "zod";
12	
13	import { getWorkerModel } from "@/lib/models";
14	import { smokeCheckpointer } from "./smoke-checkpointer";
15	
16	export const getDomainAge = tool(
17	  span(
18	    { kind: "TOOL", toolName: "get_domain_age" },
19	    async ({ domain }: { domain: string }) =>
20	      JSON.stringify({
21	        domain,
22	        ageDays: 3650,
23	        source: "fixed-smoke-stub",
24	      }),
25	  ),
26	  {
27	    name: "get_domain_age",
28	    description: "Return fixed domain-age data for the tracing smoke test.",
29	    schema: z.object({
30	      domain: z.string().min(1).describe("Domain name to inspect"),
31	    }),
32	  },
33	);
34	
35	const callModel = span(
36	  { kind: "AGENT", name: "callModel" },
37	  async (state: typeof MessagesAnnotation.State) => {
38	    const modelWithTool = getWorkerModel().bindTools([getDomainAge], {
39	      tool_choice: "get_domain_age",
40	    });
41	    const response = await modelWithTool.invoke(state.messages);
42	
43	    return { messages: [response] };
44	  },
45	);
46	
47	export const smokeGraph = new StateGraph(MessagesAnnotation)
48	  .addNode("llm", callModel)
49	  .addNode("tool", new ToolNode([getDomainAge]))
50	  .addEdge(START, "llm")
51	  .addEdge("llm", "tool")
52	  .addEdge("tool", END)
53	  .compile({ checkpointer: smokeCheckpointer });
54	
55	export function smokeGraphInput(domain = "example.com") {
56	  return {
57	    messages: [
58	      new HumanMessage(
59	        `Call get_domain_age once for ${domain}. Do not answer without the tool.`,
60	      ),
61	    ],
62	  };
63	}
