16	
17	  try {
18	    const events = await smokeGraph.stream(smokeGraphInput(), {
19	      configurable: { thread_id: runId },
20	      streamMode: ["updates", "messages"],
21	      callbacks: [handler],
22	      tags: ["variant:smoke"],
23	      runId,
24	    });
25	
26	    for await (const event of events) {
27	      // Fully consume the stream so every callback span can close before flush.
28	      void event;
29	    }
30	  } finally {
31	    const [, flushed] = await Promise.all([
32	      clearSmokeGraphThread(runId),
33	      neatlogs.flushNeatlogs(),
34	    ]);
